    return (False, None)
if not (isinstance(C, int) and isinstance(d, int) and isinstance(r, int)):
    return (False, None)
if C < 2 or d < 1 or r < 1:
    # Require at least 2 candidates, baseline gap >= 1, and positive step for hardness
    return (False, None)

# We treat 'percentage' in standard base 100.
B = 100

# Compute minimal N > B such that sum_{i=1..C} ceil(((d + r*(i-1)) * N)/(N - B)) <= N.
A = d*C + r*(C-1)*C//2
N = B + A  # necessary lower bound from ignoring ceilings
# To avoid infinite loops, we set a generous upper bound that is unlikely to be reached
max_steps = 500000
steps = 0
found = None
while steps < max_steps:
